<script>
	import { onMount } from 'svelte'; import { api } from '$lib/api.js'; import Nav from '$lib/Nav.svelte';
	let customers = $state([]), loading = $state(true), errorMessage = $state(''), search = $state('');
	async function loadCustomers() { loading = true; try { customers = await api.getCustomers(); } catch (error) { errorMessage = error?.message || 'Unable to load customers'; } finally { loading = false; } }
	let filtered = $derived(customers.filter((customer) => `${customer.name || ''} ${customer.phone || ''}`.toLowerCase().includes(search.toLowerCase()))); onMount(loadCustomers);
</script>
<Nav /><main class="app-page"><header class="page-heading"><div><p class="eyebrow">DIRECTORY</p><h1>Customers</h1><p>Customer details collected from your invoices.</p></div></header><div class="toolbar"><input class="control search" placeholder="Search name or phone…" bind:value={search}/><span class="count">{filtered.length} customers</span></div><section class="panel">{#if loading}<div class="state">Loading customers…</div>{:else if errorMessage}<div class="state error">{errorMessage}</div>{:else if filtered.length === 0}<div class="state"><h3>No customers found</h3><p>Customers will appear after an invoice is created.</p></div>{:else}<table class="data-table"><thead><tr><th>Customer</th><th>Phone</th><th>Address</th><th>Record ID</th></tr></thead><tbody>{#each filtered as customer (customer.id)}<tr><td class="strong"><span class="avatar">{customer.name?.[0]?.toUpperCase() || 'W'}</span>{customer.name || 'Walk-in customer'}</td><td>{customer.phone || '—'}</td><td>{customer.address || '—'}</td><td>#{customer.id}</td></tr>{/each}</tbody></table>{/if}</section></main>
<style>.count{padding:0 8px;color:#7a8496;font-size:12px}.avatar{display:inline-grid;width:30px;height:30px;margin-right:10px;place-items:center;border-radius:8px;background:#eef2ff;color:#315ee7;font-size:12px}</style>
